import{c as r,U as i,j as n,g as t,o as a,a6 as o,n as l}from"./chunks/framework.h4W4t1IS.js";const f=JSON.parse('{"title":"Revue de code","description":"","frontmatter":{"title":"Revue de code","status":"ready","tags":["pratiques","code-review","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"pratiques/revues-code.md","filePath":"pratiques/revues-code.md"}'),d={name:"pratiques/revues-code.md"},u={id:"frontmatter-title",tabindex:"-1"};function c(s,e,p,m,h,v){return i(),n("div",null,[t("h1",u,[a(o(s.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=l('<p>La <strong><a href="/420-w30-sf-po2/lexique.html#revue-de-code" class="lexicon-link" title="Examen du code d&#39;un pair avant intégration : lire les tests d&#39;abord, vérifier les conventions et les principes SOLID, commenter précisément et de façon constructive.">revue de code</a></strong> (<em>code review</em>) est l&#39;examen du code d&#39;un pair avant son intégration. C&#39;est une pratique professionnelle standard qui améliore la qualité du code, répand la connaissance du système dans l&#39;équipe et fait progresser tout le monde.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Préparer son code avant de demander une revue</li><li>Effectuer une revue de code selon un ordre de lecture efficace</li><li>Formuler des commentaires de revue précis et constructifs</li><li>Recevoir des commentaires de façon professionnelle</li></ul></div><p>Pour les sections suivante, on suppose que <a href="/420-w30-sf-po2/lexique.html#depot-distant" class="lexicon-link" title="Dépôt Git hébergé sur un serveur distant, permettant la collaboration et le partage de code entre plusieurs développeurs.">dépôt distant</a> est hébergé sur github.com.</p><h2 id="le-developpeur-se-preparer-avant-de-demander-une-revue" tabindex="-1">Le développeur: se préparer avant de demander une revue <a class="header-anchor" href="#le-developpeur-se-preparer-avant-de-demander-une-revue" aria-label="Permalink to &quot;Le développeur: se préparer avant de demander une revue&quot;">​</a></h2><p>Avant d&#39;assigner des réviseurs :</p><ol><li><strong>Ouvrir la revue de code</strong> - ouvrir la revue de code sur github.com en sélectionnant la branche source (fonctionnalité) et la branche de destination (<code>develop</code>)</li><li><strong>Relire ses propres changements</strong> - onglet « Files changed »</li><li><strong>Vérifier le formatage</strong> - indentation, noms de méthodes</li><li><strong>Valider que les tests couvrent les changements</strong></li><li><strong>Ajouter des commentaires</strong> sur les parties complexes, directement dans l&#39;interface de revue</li></ol><div class="tip custom-block"><p class="custom-block-title">Réduire l&#39;effort du réviseur</p><p>Une revue plus rapide et plus juste commence par un changement plus facile à lire. Se relire soi-même en premier est une marque de respect envers le temps du réviseur.</p></div><h2 id="le-reviseur-effectuer-une-revue-de-code" tabindex="-1">Le réviseur: effectuer une revue de code <a class="header-anchor" href="#le-reviseur-effectuer-une-revue-de-code" aria-label="Permalink to &quot;Le réviseur: effectuer une revue de code&quot;">​</a></h2><p>Ordre de lecture recommandé :</p><ol><li><strong>Lire la description</strong> - comprendre le contexte et l&#39;objectif du changement</li><li><strong>Survoler les fichiers modifiés</strong> - est-ce que tous ces fichiers font partie du changement?</li><li><strong>Lire les tests en premier</strong> - ils documentent le comportement attendu</li><li><strong>Réviser le code de production</strong> - est-ce que le code fait ce que les tests décrivent?</li><li><strong>Vérifier les conventions</strong> - nommage, structure, respect des principes et standards de programmation</li><li><strong>Approuver</strong> (Approve) ou <strong>demander des modifications</strong> (Request changes) avec des commentaires précis</li></ol><h3 id="criteres-de-revue" tabindex="-1">Critères de revue <a class="header-anchor" href="#criteres-de-revue" aria-label="Permalink to &quot;Critères de revue&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Critère</th><th>Questions à se poser</th></tr></thead><tbody><tr><td>Tests</td><td>Les cas importants sont-ils couverts?</td></tr><tr><td>Nommage</td><td>Les noms sont-ils clairs sans commentaires?</td></tr><tr><td>Complexité</td><td>La méthode est-elle trop longue ou trop complexe?</td></tr><tr><td>Duplication</td><td>Y a-t-il du code répété qui devrait être extrait?</td></tr><tr><td>Qualité générale</td><td>Le code est lisible et mets en pratiques les standards de programmations attendus</td></tr><tr><td><a href="/420-w30-sf-po2/lexique.html#precondition" class="lexicon-link" title="Condition qui doit être vraie avant l&#39;exécution d&#39;une méthode ou d&#39;une fonction pour garantir son bon fonctionnement.">Préconditions</a></td><td>Les entrées invalides sont-elles rejetées?</td></tr></tbody></table><h2 id="formuler-un-commentaire-de-revue" tabindex="-1">Formuler un commentaire de revue <a class="header-anchor" href="#formuler-un-commentaire-de-revue" aria-label="Permalink to &quot;Formuler un commentaire de revue&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># ✗ Commentaire vague ou négatif</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ce code est mauvais.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># ✓ Commentaire précis et constructif</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ligne 42 : Cette méthode a 4 paramètres. As-tu envisagé de regrouper</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`nom`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`prenom`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> et </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`adresse`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dans un objet </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`InfosContact`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?</span></span></code></pre></div><p><strong>Structure d&#39;un bon commentaire :</strong></p><ol><li>Identifier précisément (ligne, méthode, classe) - l&#39;interface Web de github le fait pour nous</li><li>Décrire le problème (sans jugement) - rester factuel sur le code sous vos yeux</li><li>Proposer une piste de solution - le but est d&#39;entâmer une discussion</li></ol><div class="tip custom-block"><p class="custom-block-title">Revue bienveillante</p><p>Une revue de code porte sur le code, pas sur la personne. Formuler les commentaires comme des questions ou des suggestions : « As-tu envisagé... ? » plutôt que « Tu aurais dû... ».</p></div><h2 id="recevoir-des-commentaires" tabindex="-1">Recevoir des commentaires <a class="header-anchor" href="#recevoir-des-commentaires" aria-label="Permalink to &quot;Recevoir des commentaires&quot;">​</a></h2><ul><li>Les commentaires portent sur le <strong>code</strong>, pas sur toi</li><li>Chaque commentaire est une occasion d&#39;apprendre</li><li>Si on n&#39;est pas d&#39;accord, <strong>en discuter</strong> - ne pas ignorer</li><li>Répondre à chaque commentaire (résolu, en discussion, ou avec une question)</li></ul><div class="tip custom-block"><p class="custom-block-title">Approche saine</p><p>Personne n&#39;écrit du code parfait du premier coup. L&#39;objectif d&#39;une revue est que le code soit meilleur et que tous les membres de l&#39;équipe apprennent.</p></div>',21))])}const k=r(d,[["render",c]]);export{f as __pageData,k as default};
